WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_text_material'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '文字资料', 'kp-xingce-data-analysis-text-material', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "文字资料综述"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "全篇由汉字和数字穿插组成的材料，数据隐蔽性最强，极耗时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "没有图表，只有长篇大论的文字。它的难点不在于计算，而在于找数慢、易看串行。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题结论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "突破文字资料的关键在于“结构化阅读”。文字资料往往有极强的逻辑结构（总分、并列），必须在做题前先建构脑内地图。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到文字材料, 绝对不要通读全文!] --> B[花20秒执行结构化扫读]\nB --> C[扫段落首句: 确认每段的主体(如一段农业、一段工业)]\nC --> D[扫重点标点: 遇到句号划竖线切分, 遇到分号找并列]\nD --> E[扫关键词: 圈出'其中'、'分别'等带数据的信号词]\nE --> F[形成脑内目录, 开始看题干直接空降定位]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导（阅读示例）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【材料】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年全国粮食产量69541万吨。其中，夏粮产量14615万吨；早稻产量283万吨；秋粮产量54643万吨。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "扫第一句：看到句号停，得知大盘子是“全国总产量”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找信号词：看到“其中”，说明后面要开始拆分子集了。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看标点：看到两个分号“；”，说明被拆成了三个并列块。脑内立刻生成：总 = 夏 + 早 + 秋。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先读材料再做题：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "文字资料信息量过载，读完必定全忘。必须“先看题，圈出题干的时间和主体，再带着目标回文定位”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "用红笔练习在材料上“划重点”。画出所有的句号和分号，让密密麻麻的文字变成清晰的豆腐块。"}]}]}$$ AS jsonb), NULL, '文字资料的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "文字资料"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_text_material", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
